def bis(f, lo, hi, n=200):
    flo = f(lo)
    for _ in range(n):
        m = (lo + hi) / 2
        fm = f(m)
        if (flo <= 0) == (fm <= 0):
            lo, flo = m, fm
        else:
            hi = m
    return (lo + hi) / 2

def _area(t):
    s = t + 2**t
    xb = bis(lambda x: 2**(x-4) - 4 - (s - x), -50, 50)
    yb = s - xb
    return abs(t*yb - xb*2**t) / 2

def skill():
    s = Rational(40, 2)
    t = next(k for k in range(1, 30) if k + 2**k == s)
    return t * 2**t

def standard():
    t = bis(lambda t: _area(t) - 40, 0.001, 30)
    return round(t * 2**t)

def unique():
    xs = [0.01 + 0.05*k for k in range(500)]
    vals = [_area(x) for x in xs]
    assert all(v2 > v1 for v1, v2 in zip(vals, vals[1:]))
    return [standard()]
